export function getDiscoveredPlugin(codeOrSlug: string): GamePlugin | undefined {
  const normalized = (codeOrSlug || '').toLowerCase().trim();
  if (DISCOVERED_PLUGINS[normalized]) return DISCOVERED_PLUGINS[normalized];
  for (const [key, plugin] of Object.entries(DISCOVERED_PLUGINS)) {
    if (normalized.includes(key) || key.includes(normalized) || plugin.id === normalized) {
      return plugin;
    }
  }
  return undefined;
}

export function getAllDiscoveredPlugins(): GamePlugin[] {
  return Object.values(DISCOVERED_PLUGINS);
}
